pub async fn append_entries(&mut self, req: AppendRequest) -> Result<AppendResponse> {
    let state = self.consensus_state.lock().await;
    if req.term < state.current_term {
        return Ok(AppendResponse { success: false, term: state.current_term });
    }
    self.log.commit_to(req.leader_commit).await?;
    Ok(AppendResponse { success: true, term: state.current_term })
}

@app.post('/api/events/ingest')
async def ingest_telemetry_batch(batch: TelemetryBatch):
    pipe = kafka_producer.pipeline()
    for event in batch.events:
        await pipe.send_raw('telemetry-v1', event.serialize())
    return {'status': 'ingested', 'count': len(batch.events)}

